#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn tiled_matmul_k64_n32_test() {
        let mut ctx = Context::acquire();

        let mut x_tiles: Vec<Vec<bf16>> = vec![vec![]; 4];
        let mut w_tiles: Vec<Vec<Vec<bf16>>> = vec![vec![vec![]; 4]; 4];

                    x_tiles[0] = X_DATA[0..16].iter().map(|&v| bf16::from_f32(v)).collect();
            x_tiles[1] = X_DATA[16..32].iter().map(|&v| bf16::from_f32(v)).collect();
            x_tiles[2] = X_DATA[32..48].iter().map(|&v| bf16::from_f32(v)).collect();
            x_tiles[3] = X_DATA[48..64].iter().map(|&v| bf16::from_f32(v)).collect();
                    w_tiles[0][0] = W_N0_K0_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[0][1] = W_N0_K1_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[0][2] = W_N0_K2_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[0][3] = W_N0_K3_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[1][0] = W_N1_K0_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[1][1] = W_N1_K1_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[1][2] = W_N1_K2_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[1][3] = W_N1_K3_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[2][0] = W_N2_K0_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[2][1] = W_N2_K1_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[2][2] = W_N2_K2_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[2][3] = W_N2_K3_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[3][0] = W_N3_K0_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[3][1] = W_N3_K1_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[3][2] = W_N3_K2_F32.iter().map(|&v| bf16::from_f32(v)).collect();
            w_tiles[3][3] = W_N3_K3_F32.iter().map(|&v| bf16::from_f32(v)).collect();

        let out = tiled_matmul_64x32(&mut ctx, &x_tiles, &w_tiles).await;

        let exp_norm: f32 = EXPECT.iter().map(|v| v*v).sum::<f32>().sqrt();
        let out_norm: f32 = out.iter().map(|v| v*v).sum::<f32>().sqrt();
        println!("기대 norm: {exp_norm:.4}, 실제 norm: {out_norm:.4}");

        for i in 0..32 {
            let diff = (EXPECT[i] - out[i]).abs();
            println!("  [{i:2}] PyTorch={:.4} RNGD={:.4} diff={:.4}", EXPECT[i], out[i], diff);
        }

        let mut fail = 0;
        for i in 0..32 {
            let tol = (EXPECT[i].abs() * 0.10_f32).max(1.0_f32);
            if (EXPECT[i] - out[i]).abs() > tol { fail += 1; }
        }
        assert!(fail == 0, "타일링 불일치: {fail}/32");
        println!("✅ PASS: K=64, N=32 타일링 검증 성공");
    }
}
